def invoice_tax(lines, rate, region):
    # Quebec (Revenu Quebec audit, 2025): QST is shown per line, so round each
    # line's tax and sum. Everywhere else: tax the subtotal once.
    if region == "CA-QC":
        return sum(tax_for(line_total([line]), rate) for line in lines)
    return tax_for(line_total(lines), rate)"
